def make_finding(raw):
    fid, name, description, refs, value_kind, required = raw
    first_kind = next((kind for token, kind in [
        ("identifier","identity"),("mandate","authority"),("problem","definition"),
        ("objective","requirement"),("causal","relationship"),("audience","classification"),
        ("eligibility","privacy"),("phase","composition"),("schedule","temporal"),
        ("message","definition"),("channel","interoperability"),("team","ownership"),
        ("decision","decision"),("budget","measurement"),("risk","security"),
        ("draft","lifecycle"),("plan-release","lifecycle"),("metric","measurement"),
        ("delivery","evidence"),("attribution","evidence"),("evaluation","decision"),
        ("stix","interoperability"),("role-view","access")
    ] if token in fid), "definition")
    return {"id":fid,"name":name,"description":description,"source_refs":refs,"questions":[
        {"id":fid+"-q01","text":f"What identifiers, types, roles, scope, versions and values define {name.lower()}?","kind":first_kind,"answer_data":["identifiers","types and roles","scope and versions","values and explicit unknowns"]},
        {"id":fid+"-q02","text":f"Which authority, source, method, evidence, event time and knowledge time support {name.lower()}?","kind":"provenance","answer_data":["authority","source and method","evidence","event and knowledge time","confidence and uncertainty"]},
        {"id":fid+"-q03","text":f"How is {name.lower()} validated, accessed, changed, contested, corrected and retained?","kind":"validation","answer_data":["validation","access and disclosure","change and dispute","lineage","retention"]}],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured campaign data for "+name.lower()+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing campaign record for "+name.lower()+" with authority, time, provenance and access marking.","media_or_form":["logical campaign assertion","plan, assignment, event, observation or evidence reference"],"serial":True,"identity_strategy":"Campaign identifier plus phase or wave discriminator when applicable plus "+fid+" assertion, artifact or event identifier; name, date, timestamp and digest never identify the campaign alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    bundles = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        made_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            made_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":[make_finding(f) for f in findings]})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":made_layers})
    return {"bundles":bundles}

